```json
{
  "root_causes": [
    {
      "service": "ts-contacts-service",
      "fault_kind": "network_loss",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.attr_k8s_pod_name client_pod, s.attr_k8s_pod_name server_pod, count(*) n, quantile_cont(c.duration,0.5)/1e6 p50, quantile_cont(c.duration,0.95)/1e6 p95, quantile_cont(s.duration,0.5)/1e6 srv_p50 FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-preserve-service' AND c.span_name='GET' AND s.attr_span_kind='Server' GROUP BY ALL ORDER BY p95 DESC LIMIT 20",
          "claim": "Preserve's GET calls to contacts take ~1.7s p50 and 53s p95, while contacts' server spans stay ~7ms."
        },
        {
          "kind": "metric",
          "sql": "SELECT src, metric, attr_source, attr_destination, count(*) n, sum(value) total FROM (SELECT 'abn' src, * FROM abnormal_metrics_sum UNION ALL SELECT 'norm', * FROM normal_metrics_sum) WHERE metric = 'hubble_drop_total' AND attr_destination LIKE '%ts-preserve-service%' GROUP BY ALL ORDER BY 2,1,3,4",
          "claim": "Hubble drops during the incident are concentrated on the contacts→preserve pod pair (40 drops), absent in the normal period."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-contacts-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.attr_k8s_pod_name client_pod, s.attr_k8s_pod_name server_pod, count(*) n, quantile_cont(c.duration,0.5)/1e6 p50, quantile_cont(c.duration,0.95)/1e6 p95, quantile_cont(s.duration,0.5)/1e6 srv_p50 FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-preserve-service' AND c.span_name='GET' AND s.attr_span_kind='Server' GROUP BY ALL ORDER BY p95 DESC LIMIT 20",
          "claim": "Slow contacts calls inflate preserve's own GET client spans to 53s p95, and preserve's own time rises to ~3s p95."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT src, service_name, span_name, count(*) n, quantile_cont(duration,0.5)/1e6 p50, quantile_cont(duration,0.95)/1e6 p95 FROM (SELECT 'abn' src,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%preserve%' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "ui-dashboard's preserve requests slow from 182ms p50 to 4.5s p50 and 1.5s to 20s p95 during the incident."
        }
      ]
    }
  ]
}
